// Development / unbuilt service worker: does nothing except remove any cache an earlier version left behind.
// The real offline worker is GENERATED by `npm run build` (scripts/build.mjs) with a cache name that changes on every
// release, so a deploy can never serve a mix of old and new files. Serve the built `dist/` folder in production.

self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', event => {
  event.waitUntil(
    caches
      .keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('aeii-')).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});
